class Solution {
public:
    int maxSum(std::vector<int>& nums1, std::vector<int>& nums2) {
        const int MOD = 1e9 + 7;
        int i = 0, j = 0, n = nums1.size(), m = nums2.size();
        long long sum1 = 0, sum2 = 0;
        while (i < n && j < m) {
            if (nums1[i] < nums2[j]) {
                sum1 += nums1[i++];
            } else if (nums2[j] < nums1[i]) {
                sum2 += nums2[j++];
            } else {
                long long common = std::max(sum1, sum2) + nums1[i];
                sum1 = sum2 = common;
                i++; j++;
            }
        }
        while (i < n) sum1 += nums1[i++];
        while (j < m) sum2 += nums2[j++];
        return std::max(sum1, sum2) % MOD;
    }
};

