        final int MOD = 1000000007;
        int i = 0, j = 0, n = nums1.length, m = nums2.length;
        long sum1 = 0, sum2 = 0;
        while (i < n && j < m) {
            if (nums1[i] < nums2[j]) {
                sum1 += nums1[i++];
            } else if (nums2[j] < nums1[i]) {
                sum2 += nums2[j++];
            } else {
                long common = Math.max(sum1, sum2) + nums1[i];
                sum1 = sum2 = common;
                i++; j++;
            }
        }
        while (i < n) sum1 += nums1[i++];
        while (j < m) sum2 += nums2[j++];
        return (int)(Math.max(sum1, sum2) % MOD);
    }
}

